const fs = require('fs');
const path = require('path');

const items = $input.all();
if (items.length === 0) throw new Error('Input vacío en Motor Render');
const item = items[0].json;

let logoPath = item.logoPath || '/data/logo2.jpeg';
let productoPath = item.productoPath || item.path;
const marca = item.marca || 'yourbrand';

if (item.parameter && Array.isArray(item.parameter)) {
  item.parameter.forEach(p => {
    if (p.name === 'productoPath') productoPath = p.value;
    if (p.name === 'logoPath') logoPath = p.value;
  });
}

if (!productoPath) throw new Error('Faltan rutas de origen (productoPath/path)');

const category = item.categoryRaw || 'Sin_Categoria';
const fileName = item.fileName || path.basename(productoPath);
const destinoPath = `/data/fotosProcesadas/${marca}/${category}/${fileName}`;

const targetDir = path.dirname(destinoPath);
if (!fs.existsSync(targetDir)) fs.mkdirSync(targetDir, { recursive: true });

try {
  const logoBuffer = fs.readFileSync(logoPath);
  const prodBuffer = fs.readFileSync(productoPath);

  if (!logoBuffer) throw new Error('LOGO no cargó');
  if (!prodBuffer) throw new Error('PRODUCTO no cargó');

  const getMime = (p) => {
    const ext = path.extname(p).toLowerCase();
    return (ext === '.png') ? 'image/png' : (ext === '.webp') ? 'image/webp' : 'image/jpeg';
  };

  return [{
    json: {
      ...item,
      logoBase64: logoBuffer.toString('base64'),
      productoBase64: prodBuffer.toString('base64'),
      logoMime: getMime(logoPath),
      productoMime: getMime(productoPath),
      destinoPath,
      marca
    }
  }];
} catch (e) {
  throw new Error('FALLO LECTURA: ' + e.message + ' | ' + productoPath);
}

